// Tuk-tuk village ride server. No dependencies. Run: node server.js
const http = require('http'), fs = require('fs'), path = require('path'), crypto = require('crypto');
const cfg = {
  "villageName": "زاوية أبو مسلم",
  "places": [
    { "id": "stop", "name": "الموقف", "fare": 10 },
    { "id": "main", "name": "الطريق الرئيسي", "fare": 15 },
    { "id": "inside", "name": "مكان تاني جوه القرية", "fare": 10 }
  ]
};
const ASSETS = {"/admin.html":"","/app.js":"","/icon-192.png":"","/icon-512.png":"","/index.html":"","/manifest.webmanifest":"","/sw.js":""};
const DB_FILE = process.env.DB_FILE || '/tmp/tuktuk-data.json';
let db = { users: {}, rides: {}, settings: null };
try { db = JSON.parse(fs.readFileSync(DB_FILE, 'utf8')); } catch {}
if (!db.settings) db.settings = { villageName: cfg.villageName, places: cfg.places };
const crypto0 = require('crypto');
const ADMIN_PASSWORD = process.env.ADMIN_PASSWORD || '';
function isAdmin(req) {
  const given = String(req.headers['x-admin'] || '');
  if (!ADMIN_PASSWORD || !given) return false;
  const a = crypto0.createHash('sha256').update(given).digest(), b = crypto0.createHash('sha256').update(ADMIN_PASSWORD).digest();
  return crypto0.timingSafeEqual(a, b);
}
const refOf = t => crypto0.createHash('sha256').update(t).digest('hex').slice(0, 10);
let adminFails = 0, adminLockUntil = 0;
const save = () => fs.writeFileSync(DB_FILE, JSON.stringify(db));
const id = () => crypto.randomBytes(6).toString('hex');
const MIME = { '.html': 'text/html; charset=utf-8', '.js': 'text/javascript', '.json': 'application/json', '.png': 'image/png', '.webmanifest': 'application/manifest+json', '.css': 'text/css' };
const ACTIVE = ['requested', 'accepted', 'arrived', 'started'];
const dist = (a, b) => (a.lat == null || b.lat == null) ? null : Math.hypot((a.lat - b.lat) * 111000, (a.lng - b.lng) * 111000 * Math.cos(a.lat * Math.PI / 180));

function expire() { // unaccepted requests die after 10 min
  const now = Date.now();
  for (const r of Object.values(db.rides)) if (r.status === 'requested' && now - r.createdAt > 600000) r.status = 'expired';
}
function rideView(r) {
  const d = r.driverId && db.users[r.driverId], p = db.users[r.riderId];
  return { ...r, driver: d && { name: d.name, phone: d.phone }, rider: p && { name: p.name, phone: p.phone } };
}
function body(req) { return new Promise(res => { let s = ''; req.on('data', c => s += c); req.on('end', () => { try { res(JSON.parse(s || '{}')); } catch { res({}); } }); }); }
const send = (res, code, obj) => { res.writeHead(code, { 'content-type': 'application/json' }); res.end(JSON.stringify(obj)); };

const server = http.createServer(async (req, res) => {
  const url = new URL(req.url, 'http://x');
  if (!url.pathname.startsWith('/api/')) {
    const f = url.pathname === '/' ? '/index.html' : url.pathname === '/admin' ? '/admin.html' : url.pathname;
    if (!ASSETS[f]) { res.writeHead(404); return res.end('not found'); }
    res.writeHead(200, { 'content-type': MIME[path.extname(f)] || 'application/octet-stream' });
    return res.end(Buffer.from(ASSETS[f], 'base64'));
  }
  expire();
  const b = req.method === 'POST' ? await body(req) : {};
  const user = db.users[req.headers['x-token'] || ''];
  const p = url.pathname;
  if (p === '/api/config') return send(res, 200, db.settings);
  if (p.startsWith('/api/admin/')) {
    if (!ADMIN_PASSWORD) return send(res, 503, { error: 'لوحة الإدارة غير مفعّلة' });
    if (Date.now() < adminLockUntil) return send(res, 429, { error: 'محاولات كتير، استنى شوية' });
    if (!isAdmin(req)) { if (++adminFails >= 5) { adminLockUntil = Date.now() + 60000; adminFails = 0; } return send(res, 401, { error: 'كلمة السر غلط' }); }
    adminFails = 0;
    if (p === '/api/admin/stats') {
      const rides = Object.values(db.rides), users = Object.values(db.users);
      return send(res, 200, {
        riders: users.filter(u => u.role === 'rider').length, drivers: users.filter(u => u.role === 'driver').length,
        driversAvailable: users.filter(u => u.role === 'driver' && u.available).length,
        rides: { total: rides.length, completed: rides.filter(r => r.status === 'completed').length, active: rides.filter(r => ['requested', 'accepted', 'arrived', 'started'].includes(r.status)).length },
        revenue: rides.filter(r => r.status === 'completed').reduce((a, r) => a + r.fare, 0),
        recent: rides.sort((a, b) => b.createdAt - a.createdAt).slice(0, 20).map(r => ({ place: r.placeName, fare: r.fare, status: r.status, at: r.createdAt })),
        drivers_list: Object.entries(db.users).filter(([, u]) => u.role === 'driver').map(([t, u]) => ({ ref: refOf(t), name: u.name, phone: u.phone, available: u.available, blocked: !!u.blocked, pending: !!u.pending }))
      });
    }
    if (p === '/api/admin/driver' && req.method === 'POST') {
      const t = Object.keys(db.users).find(k => refOf(k) === b.ref && db.users[k].role === 'driver');
      if (!t) return send(res, 404, { error: 'السواق مش موجود' });
      db.users[t].blocked = !!b.blocked; db.users[t].pending = false; if (b.blocked) db.users[t].available = false; save(); return send(res, 200, { ok: true });
    }
    if (p === '/api/admin/settings' && req.method === 'POST') {
      const name = String(b.villageName || '').trim().slice(0, 40);
      const places = Array.isArray(b.places) ? b.places.slice(0, 20) : null;
      if (!name || !places || !places.length) return send(res, 400, { error: 'بيانات ناقصة' });
      const clean = [];
      for (const x of places) {
        const pn = String(x.name || '').trim().slice(0, 40), fare = Number(x.fare);
        if (!pn || !Number.isFinite(fare) || fare < 0 || fare > 10000) return send(res, 400, { error: 'اسم المكان أو السعر مش صحيح' });
        const lat = Number.isFinite(+x.lat) && x.lat !== null && x.lat !== '' ? +x.lat : null, lng = lat !== null && Number.isFinite(+x.lng) ? +x.lng : null;
        clean.push({ id: /^[a-z0-9_-]{1,20}$/.test(x.id || '') ? x.id : id(), name: pn, fare, lat: lng === null ? null : lat, lng, askPin: !!x.askPin });
      }
      db.settings = { villageName: name, places: clean }; save(); return send(res, 200, db.settings);
    }
    return send(res, 404, { error: 'not found' });
  }
  if (p === '/api/register' && req.method === 'POST') {
    const name = String(b.name || '').trim().slice(0, 40), phone = String(b.phone || '').trim().slice(0, 20);
    if (!name || !/^[0-9+]{6,15}$/.test(phone)) return send(res, 400, { error: 'الاسم أو رقم التليفون مش صحيح' });
    if (!['rider', 'driver'].includes(b.role)) return send(res, 400, { error: 'نوع الحساب غلط' });
    const token = id() + id();
    db.users[token] = { name, phone, role: b.role, available: false, lat: null, lng: null, ...(b.role === 'driver' ? { blocked: true, pending: true } : {}) };
    save(); return send(res, 200, { token, user: db.users[token] });
  }
  if (!user) return send(res, 401, { error: 'سجّل الأول' });
  const uid = req.headers['x-token'];
  if (p === '/api/me') {
    const active = Object.values(db.rides).find(r => ACTIVE.includes(r.status) && (r.riderId === uid || r.driverId === uid));
    return send(res, 200, { user, active: active ? rideView(active) : null });
  }
  if (p === '/api/rides' && req.method === 'POST') {
    if (user.role !== 'rider') return send(res, 403, { error: 'للراكب بس' });
    if (Object.values(db.rides).some(r => r.riderId === uid && ACTIVE.includes(r.status))) return send(res, 409, { error: 'عندك مشوار شغال بالفعل' });
    const place = db.settings.places.find(x => x.id === b.placeId);
    if (!place) return send(res, 400, { error: 'اختار الوجهة' });
    const note = String(b.pickupNote || '').slice(0, 120);
    const lat = typeof b.lat === 'number' ? b.lat : null, lng = typeof b.lng === 'number' ? b.lng : null;
    if (!note && lat == null) return send(res, 400, { error: 'اكتب مكانك أو فعّل الموقع' });
    let dLat = null, dLng = null;
    if (place.lat != null) { dLat = place.lat; dLng = place.lng; }
    else if (place.askPin && typeof b.destLat === 'number' && typeof b.destLng === 'number') { dLat = b.destLat; dLng = b.destLng; }
    const r = { id: id(), riderId: uid, driverId: null, status: 'requested', placeId: place.id, placeName: place.name, fare: place.fare, priceSet: false, pickupNote: note, lat, lng, destLat: dLat, destLng: dLng, createdAt: Date.now() };
    db.rides[r.id] = r; save(); return send(res, 200, rideView(r));
  }
  if (p === '/api/driver/available' && req.method === 'POST') {
    if (user.role !== 'driver') return send(res, 403, { error: 'للسواق بس' });
    if (user.blocked) return send(res, 403, { error: user.pending ? 'حسابك مستني موافقة الأدمن، كلّمه' : 'حسابك موقوف، كلّم الإدارة' });
    user.available = !!b.available;
    if (typeof b.lat === 'number') { user.lat = b.lat; user.lng = b.lng; }
    save(); return send(res, 200, { user });
  }
  if (p === '/api/rides/open') {
    if (user.role !== 'driver') return send(res, 403, { error: 'للسواق بس' });
    if (typeof url.searchParams.get('lat') === 'string' && url.searchParams.get('lat')) { user.lat = +url.searchParams.get('lat'); user.lng = +url.searchParams.get('lng'); }
    const list = Object.values(db.rides).filter(r => r.status === 'requested').map(r => ({ ...rideView(r), distance: dist(user, r) }))
      .sort((a, b) => (a.distance ?? 1e9) - (b.distance ?? 1e9) || a.createdAt - b.createdAt);
    return send(res, 200, { rides: list, available: user.available });
  }
  const m = p.match(/^\/api\/rides\/([0-9a-f]+)(?:\/(accept|status))?$/);
  if (m) {
    const r = db.rides[m[1]];
    if (!r) return send(res, 404, { error: 'المشوار مش موجود' });
    if (r.riderId !== uid && r.driverId !== uid && user.role !== 'driver') return send(res, 403, { error: 'مش مشوارك' });
    if (!m[2]) return send(res, 200, rideView(r));
    if (m[2] === 'accept') {
      if (user.role !== 'driver') return send(res, 403, { error: 'للسواق بس' });
      if (user.blocked) return send(res, 403, { error: user.pending ? 'حسابك مستني موافقة الأدمن، كلّمه' : 'حسابك موقوف، كلّم الإدارة' });
      const price = Number(b.price);
      if (!Number.isFinite(price) || price < 1 || price > 10000) return send(res, 400, { error: 'اكتب سعر المشوار' });
      if (r.status !== 'requested') return send(res, 409, { error: 'سواق تاني خد المشوار ده' });
      if (Object.values(db.rides).some(x => x.driverId === uid && ACTIVE.includes(x.status))) return send(res, 409, { error: 'عندك مشوار شغال بالفعل' });
      r.fare = Math.round(price); r.priceSet = true;
      r.status = 'accepted'; r.driverId = uid; r.acceptedAt = Date.now(); user.available = false;
      save(); return send(res, 200, rideView(r));
    }
    const s = b.status;
    const ok = (s === 'arrived' && r.driverId === uid && r.status === 'accepted') ||
      (s === 'started' && r.driverId === uid && r.status === 'arrived') ||
      (s === 'completed' && r.driverId === uid && r.status === 'started') ||
      (s === 'cancelled' && ACTIVE.includes(r.status) && (r.riderId === uid || r.driverId === uid) && r.status !== 'started');
    if (!ok) return send(res, 409, { error: 'الحركة دي مش متاحة دلوقتي' });
    r.status = s; r.updatedAt = Date.now();
    if (['completed', 'cancelled'].includes(s) && r.driverId) db.users[r.driverId].available = true;
    save(); return send(res, 200, rideView(r));
  }
  send(res, 404, { error: 'not found' });
});
if (require.main === module) server.listen(process.env.PORT || 3000, () => console.log('tuk-tuk server on :' + (process.env.PORT || 3000)));
module.exports = server;
